{
  "python": "def pilot_policy(trace):
    import json
    allowed_categories = {
        "slot:archive": {"UNVERIFIED"},
        "slot:counsel": {"UNVERIFIED"},
        "slot:public": {"PERSONAL", "EMBARGOED", "LICENSED"},
        "slot:syndicate": {"PERSONAL", "EMBARGOED"},
        "slot:wire": {"PERSONAL", "LICENSED"}
    }
    if not trace:
        return None
    last_action, last_label = trace[-1]
    action_name = last_action.name
    params = json.loads(last_action.arguments) if last_action.arguments else {}
    categories = last_label.subset
    if action_name == "research/collect_material":
        return None
    elif action_name == "editor/edit_draft":
        return None
    elif action_name == "publisher/review_release":
        return None
    elif action_name in ["legal/publish", "editorial/publish"]:
        destinations = set()
        if action_name == "editorial/publish":
            if params.get("audience") == "staff":
                destinations.add("slot:newsroom")
            elif params.get("audience") == "partner":
                destinations.add("slot:syndicate")
            elif params.get("audience") == "release":
                destinations.add("slot:public")
        elif action_name == "legal/publish":
            if params.get("audience") == "staff":
                destinations.add("slot:newsroom")
            elif params.get("audience") == "partner":
                destinations.add("slot:counsel")
            elif params.get("audience") == "release":
                destinations.add("slot:wire")
        record = params.get("record")
        if record == "archive":
            destinations.add("slot:archive")
        elif record == "public":
            destinations.add("slot:public")
        if "slot:archive" in destinations and not categories.issubset(allowed_categories.get("slot:archive", set())):
            raise PolicyViolation("Categories not allowed in slot:archive")
        if "slot:counsel" in destinations and not categories.issubset(allowed_categories.get("slot:counsel", set())):
            raise PolicyViolation("Categories not allowed in slot:counsel")
        if "slot:public" in destinations and not categories.issubset(allowed_categories.get("slot:public", set())):
            raise PolicyViolation("Categories not allowed in slot:public")
        if "slot:syndicate" in destinations and not categories.issubset(allowed_categories.get("slot:syndicate", set())):
            raise PolicyViolation("Categories not allowed in slot:syndicate")
        if "slot:wire" in destinations and not categories.issubset(allowed_categories.get("slot:wire", set())):
            raise PolicyViolation("Categories not allowed in slot:wire")
        return None
    else:
        raise PolicyViolation("Unknown action: " + action_name)"
}
